using System.IO;
using BenchmarkDotNet.Attributes;
using OneImage.Codecs.Jpx;

namespace OneImage.Benchmarks.Jpx;

/// <summary>
/// JPEG 2000 decodes of four representative files: three generated by <c>tools/gen-jpx-bench.py</c> (a lossy 3 MP RGB photo-like
/// image untiled and in 256-pixel tiles, and a 6 MP lossless gray) and the 12-bit 2048x2048x3 conformance stream p0_07 (256 tiles).
/// <c>ONEIMAGE_JPX_BENCH</c> names the generated files, <c>ONEIMAGE_JPX_CORPUS</c> the conformance data.
/// </summary>
[MemoryDiagnoser]
public class JpxBenchmarks
{
    private byte[] _data = null!;

    [Params("lossy-1tile.jp2", "lossy-tiles256.jp2", "lossless-gray.j2k", "p0_07.j2k")]
    public string File { get; set; } = "";

    [Params(0, 3)]
    public int Reduction { get; set; }

    [GlobalSetup]
    public void Setup()
    {
        string? path;
        if (File == "p0_07.j2k")
        {
            string dir = Environment.GetEnvironmentVariable("ONEIMAGE_JPX_CORPUS") ?? throw new InvalidOperationException("set ONEIMAGE_JPX_CORPUS");
            path = Path.Combine(dir, "input", "conformance", File);
        }
        else
        {
            string dir = Environment.GetEnvironmentVariable("ONEIMAGE_JPX_BENCH") ?? throw new InvalidOperationException("set ONEIMAGE_JPX_BENCH");
            path = Path.Combine(dir, File);
        }

        _data = System.IO.File.ReadAllBytes(path);
    }

    [Benchmark]
    public int Decode() => JpxCodec.Decode(_data, new JpxDecodeOptions { ReductionLevels = Reduction }).Width;
}
